from datetime import datetime, timezone
from html import escape
import json
import unittest
from unittest.mock import patch

import config
import uniclubs_database
import uniclubs_importer


NOW = datetime(2026, 11, 15, 17, 0, tzinfo=timezone.utc)
CLUB_PATH = '/hsg/clubs/example-club'
EVENT_PATH = CLUB_PATH + '/events/sample'
FETCH_TARGET = 'uniclubs_importer.importers.fetch_uniclubs_events_html'


def source_event(event_id='event-1', slug='sample', **changes):
    """Return one fictional event in the observed public page's nested structure."""
    # Course: L04 – dictionaries separate event, club and availability information.
    event = {
        'id': event_id,
        'clubId': 'club-1',
        'slug': slug,
        'title': 'Example workshop',
        'startDate': '$D2026-11-16T11:00:00.000Z',
        'endDate': '$D2026-11-16T12:00:00.000Z',
        'location': 'Online',
        'eventType': 'talk',
        'visibility': 'public',
        'status': 'published',
        'requiresMembership': False,
    }
    event.update(changes)
    return {
        'event': event,
        'club': {'id': 'club-1', 'slug': 'example-club', 'name': 'Example Club',
                 'universitySlug': 'hsg'},
        'availability': {'state': 'open'},
    }


def source_page(items, links=None, split=False):
    """Build an inert HTML fixture containing JSON-encoded React stream fragments."""
    component = ['$', '$L3a', None,
                 {'events': items, 'userClubIds': [], 'isLoggedIn': False}]
    stream = '20:' + json.dumps(component, ensure_ascii=False) + '\n'
    chunks = [stream]
    if split:
        chunks = [stream[:25], stream[25:130], stream[130:]]
    if links is None:
        links = []
        for item in items:
            links.append('/hsg/clubs/' + item['club']['slug'] +
                         '/events/' + item['event']['slug'])
    parts = ['<html><body>']
    for link in links:
        parts.append('<a href="' + escape(link, quote=True) + '">Event</a>')
    parts.append('<script>self.__next_f.push([0]);</script>')
    for chunk in chunks:
        parts.append('<script>self.__next_f.push(' + json.dumps([1, chunk]) + ')</script>')
    parts.append('</body></html>')
    return ''.join(parts)


class UniClubsImporterTests(unittest.TestCase):
    """Check source interpretation and initial writes without files or real HTTP calls."""

    def setUp(self):
        """Create only the new catalog in SQLite's memory database."""
        self.connection = uniclubs_database.get_connection(':memory:')
        self.addCleanup(self.connection.close)
        uniclubs_database.init_db(self.connection)

    def assert_empty_catalog(self):
        """Verify that no club or event was left by a failed operation."""
        self.assertEqual(self.connection.execute('SELECT count(*) FROM clubs').fetchone()[0], 0)
        self.assertEqual(uniclubs_database.get_events(self.connection), [])

    def test_public_event_normalization_retains_source_identity(self):
        """Read IDs, exact UTC times, source links and independent source states."""
        item = source_event()
        item['availability']['state'] = 'sales_closed'
        item['event']['requiresMembership'] = True
        result = uniclubs_importer.parse_events_page(source_page([item]), now=NOW)
        self.assertEqual(result['source_event_count'], 1)
        self.assertEqual(result['future_event_count'], 1)
        self.assertEqual(result['ongoing_event_count'], 0)
        self.assertEqual(len(result['clubs']), 1)
        self.assertEqual(result['clubs'][0]['external_id'], 'club-1')
        self.assertEqual(result['clubs'][0]['name'], 'Example Club')
        event = result['events'][0]
        self.assertEqual(event['external_id'], 'event-1')
        self.assertEqual(event['club_external_id'], 'club-1')
        self.assertEqual(event['start_utc'], '2026-11-16T11:00:00.000000Z')
        self.assertEqual(event['end_utc'], '2026-11-16T12:00:00.000000Z')
        self.assertEqual(event['source_url'], 'https://uniclubs.ch' + EVENT_PATH)
        self.assertEqual(event['publication_status'], 'published')
        self.assertEqual(event['availability_state'], 'sales_closed')
        self.assertTrue(event['requires_membership'])

    def test_split_stream_and_quoted_titles_are_plain_data(self):
        """Join stream fragments before decoding strings containing quotes and ); text."""
        title = 'Club\'s "Try ); again" workshop'
        result = uniclubs_importer.parse_events_page(
            source_page([source_event(title=title)], split=True), now=NOW)
        self.assertEqual(result['events'][0]['title'], title)

    def test_only_future_starts_are_imported_and_ongoing_is_counted(self):
        """Exclude historical and ongoing programs without inventing repeat occurrences."""
        future = source_event()
        past = source_event('past', 'past', startDate='$D2026-11-14T11:00:00Z',
                            endDate='$D2026-11-14T12:00:00Z')
        ongoing = source_event('ongoing', 'ongoing', startDate='$D2026-11-15T16:00:00Z',
                               endDate='$D2026-11-15T18:00:00Z')
        html = source_page([future, past, ongoing],
                           links=[EVENT_PATH, CLUB_PATH + '/events/ongoing'])
        result = uniclubs_importer.parse_events_page(html, now=NOW)
        self.assertEqual(result['source_event_count'], 3)
        self.assertEqual(result['future_event_count'], 1)
        self.assertEqual(result['ongoing_event_count'], 1)
        self.assertEqual([row['external_id'] for row in result['events']], ['event-1'])

    def test_future_event_with_unknown_end_preserves_null(self):
        """An unknown source end must not become an invented duration."""
        result = uniclubs_importer.parse_events_page(
            source_page([source_event(endDate=None)]), now=NOW)
        self.assertIsNone(result['events'][0]['end_utc'])

    def test_missing_empty_and_truncated_streams_are_rejected(self):
        """Reject error pages and partial payloads rather than treating them as no events."""
        valid = source_page([source_event()])
        candidates = ['<html>Sign in</html>', source_page([]), valid[:-40],
                      '<script>self.__next_f.push([1,"unfinished</script>']
        for html in candidates:
            with self.subTest(html=html[:50]):
                with self.assertRaises(ValueError):
                    uniclubs_importer.parse_events_page(html, now=NOW)

    def test_duplicate_event_ids_are_rejected(self):
        """Two source objects may not silently collapse into the same external event ID."""
        html = source_page([source_event(), source_event(slug='other')])
        with self.assertRaises(ValueError):
            uniclubs_importer.parse_events_page(html, now=NOW)

    def test_source_scope_and_club_references_are_checked(self):
        """Reject unrelated universities, private records and mismatched club identities."""
        wrong_club = source_event(clubId='different-club')
        private = source_event(visibility='private')
        wrong_university = source_event()
        wrong_university['club']['universitySlug'] = 'eth'
        bogus_membership = source_event(requiresMembership='yes')
        for item in (wrong_club, private, wrong_university, bogus_membership):
            with self.subTest(item=item):
                with self.assertRaises(ValueError):
                    uniclubs_importer.parse_events_page(source_page([item]), now=NOW)

    def test_required_text_and_unresolved_references_are_rejected(self):
        """Do not store missing titles, source IDs or React reference codes as event data."""
        missing_title = source_event()
        del missing_title['event']['title']
        empty_club = source_event()
        empty_club['club']['name'] = ' '
        for item in (missing_title, empty_club, source_event(title='$L123'),
                     source_event(event_id='')):
            with self.subTest(item=item):
                with self.assertRaises(ValueError):
                    uniclubs_importer.parse_events_page(source_page([item]), now=NOW)

    def test_invalid_timestamps_and_nonpositive_intervals_are_rejected(self):
        """Validate real UTC instants after removing only the source date prefix."""
        for changes in ({'startDate': None}, {'startDate': '$Dnot-a-date'},
                        {'startDate': '$D2026-11-16T11:00:00'},
                        {'endDate': '$D2026-11-16T11:00:00Z'},
                        {'endDate': '$D2026-11-16T10:00:00Z'}):
            with self.subTest(changes=changes):
                with self.assertRaises(ValueError):
                    uniclubs_importer.parse_events_page(
                        source_page([source_event(**changes)]), now=NOW)

    def test_rendered_links_detect_missing_and_unknown_source_events(self):
        """Visible event links and future source objects must be mutually consistent."""
        for links in ([], [EVENT_PATH, CLUB_PATH + '/events/missing']):
            with self.subTest(links=links):
                with self.assertRaises(ValueError):
                    uniclubs_importer.parse_events_page(
                        source_page([source_event()], links=links), now=NOW)

    def test_recently_expired_known_link_does_not_break_future_filter(self):
        """A page generated just before an event ended must remain a usable snapshot."""
        expired = source_event('expired', 'expired', startDate='$D2026-11-15T16:00:00Z',
                               endDate='$D2026-11-15T16:59:59Z')
        result = uniclubs_importer.parse_events_page(
            source_page([source_event(), expired]), now=NOW)
        self.assertEqual(result['future_event_count'], 1)
        self.assertEqual(len(result['events']), 1)

    def test_source_limit_and_naive_clock_are_rejected(self):
        """Bound record processing and require an explicit timezone for fixed clocks."""
        with patch.object(config, 'MAX_RECORDS_PER_SOURCE', 1):
            with self.assertRaises(ValueError):
                uniclubs_importer.parse_events_page(
                    source_page([source_event(), source_event('two', 'two')]), now=NOW)
        with self.assertRaises(ValueError):
            uniclubs_importer.parse_events_page(source_page([source_event()]),
                                               now=datetime(2026, 11, 15, 17, 0))

    def test_manual_import_saves_linked_rows_and_one_success_report(self):
        """The offline end-to-end path must save clubs, events and its import result."""
        with patch(FETCH_TARGET, return_value=source_page([source_event()])) as fetch:
            uniclubs_importer.run_import(self.connection, now=NOW)
        fetch.assert_called_once_with()
        rows = uniclubs_database.get_events(self.connection)
        self.assertEqual(len(rows), 1)
        self.assertEqual(rows[0]['external_id'], 'event-1')
        self.assertEqual(rows[0]['club_external_id'], 'club-1')
        logs = uniclubs_database.get_import_log(self.connection)
        self.assertEqual(len(logs), 1)
        self.assertEqual(logs[0]['status'], 'success')
        self.assertEqual(logs[0]['event_count'], 1)

    def test_parse_failure_logs_error_without_partial_catalog(self):
        """A malformed response must leave only a sanitized failed-attempt report."""
        with patch(FETCH_TARGET, return_value='<html>Service unavailable</html>'):
            with self.assertRaises(ValueError):
                uniclubs_importer.run_import(self.connection, now=NOW)
        self.assert_empty_catalog()
        logs = uniclubs_database.get_import_log(self.connection)
        self.assertEqual(len(logs), 1)
        self.assertEqual(logs[0]['status'], 'error')
        self.assertEqual(logs[0]['event_count'], 0)

    def test_populated_catalog_is_refused_before_network_access(self):
        """The initial importer must preserve existing rows until updates are implemented."""
        uniclubs_database.add_club(
            self.connection, 'existing-club', 'Existing Club',
            'https://uniclubs.ch/hsg/clubs/existing-club')
        with patch(FETCH_TARGET) as fetch:
            with self.assertRaises(ValueError):
                uniclubs_importer.run_import(self.connection, now=NOW)
        fetch.assert_not_called()
        row = self.connection.execute('SELECT * FROM clubs').fetchone()
        self.assertEqual(row['external_id'], 'existing-club')
        self.assertEqual(uniclubs_database.get_events(self.connection), [])

    def test_initial_batch_failure_rolls_back_all_clubs_and_events(self):
        """An invalid later event must undo the entire first-import write transaction."""
        result = uniclubs_importer.parse_events_page(
            source_page([source_event(), source_event('two', 'two')]), now=NOW)
        result['events'][1]['title'] = ''
        with self.assertRaises(ValueError):
            uniclubs_database.insert_initial_catalog(
                self.connection, result['clubs'], result['events'], now=NOW)
        self.assert_empty_catalog()
        self.assertEqual(uniclubs_database.get_import_log(self.connection), [])

    def test_network_failure_report_does_not_copy_exception_details(self):
        """Store a public failure summary instead of arbitrary transport error content."""
        with patch(FETCH_TARGET, side_effect=ValueError('secret-source-marker')):
            with self.assertRaises(ValueError):
                uniclubs_importer.run_import(self.connection, now=NOW)
        self.assert_empty_catalog()
        report = uniclubs_database.get_import_log(self.connection)[0]
        self.assertEqual(report['status'], 'error')
        self.assertNotIn('secret-source-marker', report['message'])


if __name__ == '__main__':
    unittest.main()
